create or replace function public.record_custody_event(p_case_id uuid, p_evidence_id uuid, p_actor_user_id uuid, p_event_type text, p_hash text default null, p_details jsonb default '{}'::jsonb) returns public.custody_events language plpgsql security invoker set search_path=public as $$ declare r public.custody_events; begin if auth.uid() is null or auth.uid() <> p_actor_user_id or not is_case_member(p_case_id) then raise exception 'not authorized'; end if; if p_event_type not in ('intake','analysis','review','download','verification') then raise exception 'invalid custody event'; end if; insert into public.custody_events(case_id,evidence_id,actor_user_id,event_type,evidence_hash,details) values(p_case_id,p_evidence_id,p_actor_user_id,p_event_type,p_hash,coalesce(p_details,'{}'::jsonb)) returning * into r; return r; end $$; revoke all on function public.record_custody_event(uuid,uuid,uuid,text,text,jsonb) from public; grant execute on function public.record_custody_event(uuid,uuid,uuid,text,text,jsonb) to authenticated;
